CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles (id,email,full_name,phone,city) VALUES (NEW.id,NEW.email,COALESCE(NEW.raw_user_meta_data->>'full_name',''),COALESCE(NEW.raw_user_meta_data->>'phone',''),COALESCE(NEW.raw_user_meta_data->>'city','')) ON CONFLICT (id) DO NOTHING; INSERT INTO public.user_roles(user_id,role) VALUES (NEW.id,'user') ON CONFLICT DO NOTHING; RETURN NEW; END; $$;
CREATE OR REPLACE FUNCTION public.get_calendar_block_ranges(range_start timestamptz, range_end timestamptz) RETURNS TABLE(start_ts timestamptz,end_ts timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT b.start_ts,b.end_ts FROM public.calendar_blocks b WHERE auth.uid() IS NOT NULL AND range_end > range_start AND b.start_ts < range_end AND b.end_ts > range_start; $$;
REVOKE ALL ON FUNCTION public.get_calendar_block_ranges(timestamptz,timestamptz) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_calendar_block_ranges(timestamptz,timestamptz) TO authenticated,service_role;
DROP POLICY IF EXISTS "Authenticated can read calendar blocks" ON public.calendar_blocks;